head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값

        }
        scwin.checkGubun();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        await scwin.checkMktactEnforceDd(); //  변경상장일 체크

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
        } else {
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05909.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05909.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05909.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05909.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05909.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_MktactEnforceDd_onclick
 * @description img_MktactEnforceDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MktactEnforceDd_onclick = function() {
    try {
        popUpCalendar2(edt_MktactEnforceDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05909.img_MktactEnforceDd_onclick" });
    }
};

/**
 * @method
 * @name btn_isunm_batch_change_onclick
 * @description 「종목명변경 일괄적용」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_isunm_batch_change_onclick = async function() {
    try {
        await scwin.changeIsuNmByBatch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05909.btn_isunm_batch_change_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name checkMktactEnforceDd
 * @description check Mktact Enforce Dd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMktactEnforceDd = async function() {
    const sbmOptions = {
        id : "sbm_dts_CheckDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_CheckDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05909.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Listing.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/Listing.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05909.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Listing.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description save Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    if (!await scwin.changeIsuNmByBatch()) return;

    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    grd_isu.redraw = false;
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }
    grd_isu.redraw = true;
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_145 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_CHGLIST_ISU_NM_CHG
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Listing.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkGubun
 * @description check Gubun 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkGubun = function() {
    if (scwin.gubun === '1') {
        // 발행사
        txb_AfchgElwIsurNm.setReadOnly(false);
        txb_AfchgElwIsurEngNm.setReadOnly(false);
        txb_AfchgUlyNm.setReadOnly(true);
        txb_AfchgUlyEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setStyle("backgroundcolor", "#b9d4f7");
        txb_AfchgUlyEngNm.setStyle("backgroundcolor", "#b9d4f7");
    } else if (scwin.gubun === '2') {
        // 기초자산
        txb_AfchgElwIsurNm.setReadOnly(true);
        txb_AfchgElwIsurEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setReadOnly(false);
        txb_AfchgUlyEngNm.setReadOnly(false);
        txb_AfchgElwIsurNm.setStyle("backgroundcolor", "#b9d4f7");
        txb_AfchgElwIsurEngNm.setStyle("backgroundcolor", "#b9d4f7");
    }
};

/**
 * @method
 * @name changeIsuNmByBatch
 * @description change Isu Nm By Batch 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeIsuNmByBatch = async function() {
    if (!await scwin.checkForm()) return false;
    grd_isu.redraw = false;
    if (scwin.gubun === '1') {
        dts_Isu.setBroadcast(false);
        for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ELW_ISUR_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ELW_ISUR_ENG_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_NM", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_NM", dts_Isu.NameString(i, "AFCHG_ISU_NM") = );*/ X = X);
            dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV2") + "호";
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_NM", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ENG_NM", dts_Isu.NameString(i, "AFCHG_ISU_ENG_NM") = );*/ X = X);
            dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV2");
        }
        dts_Isu.setBroadcast(true, true);

    } else if (scwin.gubun === '2') {
        dts_Isu.setBroadcast(false);
        for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ULY_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ULY_ENG_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_NM", dts_Isu.getCellData(i, "BFCHG_ISU_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_NM", dts_Isu.getCellData(i, "BFCHG_ISU_ENG_NM"));
        }
        dts_Isu.setBroadcast(true, true);

    }
    dts_Isu.setBroadcast(false);
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ABBRV", dts_Isu.NameString(i, "AFCHG_ISU_ABBRV") = );*/ X = X);
        dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV3") + dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV4");
        dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ENG_ABBRV", dts_Isu.NameString(i, "AFCHG_ISU_ENG_ABBRV") = );*/ X = X);
        dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV3") + dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV4");
    }
    dts_Isu.setBroadcast(true, true);
    grd_isu.redraw = true;
    return true;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MktactEnforceDd, "변경상장", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_ChgRsnContn, "상호변경사유")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComNm, "변경후한글회사명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComAbbrv, "한글회사약명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComEngNm, "영문회사명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComEngAbbrv, "영문회사약명")) return false;
    if (scwin.gubun === '1') {
        if (!$c.stf.checkEmptyValue(txb_AfchgElwIsurNm, "발행자명")) return false;
        if (!$c.stf.checkEmptyValue(txb_AfchgElwIsurEngNm, "영문발행자명")) return false;
    } else if (scwin.gubun === '2') {
        if (!$c.stf.checkEmptyValue(txb_AfchgUlyNm, "기초자산명")) return false;
        if (!$c.stf.checkEmptyValue(txb_AfchgUlyEngNm, "영문기초자산명")) return false;
    }
    if (!$c.stf.checkMaxLength(txb_ChgRsnContn, 2000, "상호변경사유")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComNm, 80, "변경후한글회사명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComAbbrv, 40, "한글회사약명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComEngNm, 80, "영문회사명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComEngAbbrv, 40, "영문회사약명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgElwIsurNm, 6, "발행자명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgElwIsurEngNm, 6, "영문발행자명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgUlyNm, 8, "기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgUlyEngNm, 8, "영문기초자산명")) return false;
    if (dts_CheckDate.getRowCount() > 0) {
        for (let i = 1; i <= dts_CheckDate.getRowCount(); i++) {
            if ((dts_CheckDate.getCellData(i, "MKTACT_ENFORCE_DD") === edt_MktactEnforceDd.getValue()) && scwin.fr_bz_procs_no === "") {
                await $c.win.alert("변경상장일에 해당하는 데이터가 존재합니다.\n변경상장일을 확인해주세요.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    let vTpl = '68953B';
    if (scwin.gubun === "2") {
        vTpl = '68953C';
    }

